'use client';
import { useState, useEffect } from 'react';
import AdminLayout from '@/components/dashboard/AdminLayout';
import Pagination from '@/components/shared/Pagination';

interface SystemLog {
  id: string;
  method: string;
  path: string;
  status: number;
  ip_address: string;
  duration: number;
  created_at: string;
}

interface Metrics {
  total: number;
  errorRate: string;
  avgDuration: number;
}

export default function SystemMetricsDashboard() {
  const [logs, setLogs] = useState<SystemLog[]>([]);
  const [metrics, setMetrics] = useState<Metrics>({ total: 0, errorRate: '0', avgDuration: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [trafficPage, setTrafficPage] = useState(1);
  const TRAFFIC_PER_PAGE = 20;

  const fetchLogs = async () => {
    try {
      const res = await fetch('/api/admin/system-logs');
      const data = await res.json();

      if (!res.ok) throw new Error(data.error || 'Failed to fetch logs');

      setLogs(data.logs);
      setMetrics(data.metrics);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs();
    // Auto-refresh every 30 seconds to monitor live traffic
    const interval = setInterval(fetchLogs, 30000);
    return () => clearInterval(interval);
  }, []);

  const getStatusColor = (status: number) => {
    if (status >= 500) return 'bg-red-100 text-red-800 border-red-200';
    if (status >= 400) return 'bg-orange-100 text-orange-800 border-orange-200';
    if (status >= 300) return 'bg-blue-100 text-blue-800 border-blue-200';
    return 'bg-green-100 text-green-800 border-green-200';
  };

  if (loading) return <div className="flex h-screen items-center justify-center bg-gray-50 dark:bg-[#0B0F19]"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#06B4C9]"></div></div>;

  return (
    <AdminLayout>
      <div className="max-w-7xl mx-auto space-y-6">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">System Monitoring</h1>
          <p className="text-gray-500 dark:text-[#94A3B8]">Live network traffic and endpoint health metrics.</p>
        </div>

        {error && (
          <div className="p-4 bg-red-50 text-red-700 rounded-lg border border-red-200">
            {error}
          </div>
        )}

        {/* KPI Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white dark:bg-[#131825] p-6 rounded-2xl shadow-sm border border-gray-200 dark:border-[#1E2536]">
            <h3 className="text-sm font-semibold text-gray-500 dark:text-[#64748B] uppercase tracking-wider">Recent Requests</h3>
            <p className="text-3xl font-bold text-gray-900 dark:text-white mt-2">{metrics.total}</p>
          </div>
          <div className="bg-white dark:bg-[#131825] p-6 rounded-2xl shadow-sm border border-gray-200 dark:border-[#1E2536]">
            <h3 className="text-sm font-semibold text-gray-500 dark:text-[#64748B] uppercase tracking-wider">Error Rate (4xx & 5xx)</h3>
            <p className={`text-3xl font-bold mt-2 ${parseFloat(metrics.errorRate) > 5 ? 'text-red-600 dark:text-red-400' : 'text-gray-900 dark:text-white'}`}>
              {metrics.errorRate}%
            </p>
          </div>
          <div className="bg-white dark:bg-[#131825] p-6 rounded-2xl shadow-sm border border-gray-200 dark:border-[#1E2536]">
            <h3 className="text-sm font-semibold text-gray-500 dark:text-[#64748B] uppercase tracking-wider">Avg Latency</h3>
            <p className={`text-3xl font-bold mt-2 ${metrics.avgDuration > 1000 ? 'text-orange-600 dark:text-orange-400' : 'text-gray-900 dark:text-white'}`}>
              {metrics.avgDuration} <span className="text-lg font-medium text-gray-500 dark:text-[#94A3B8]">ms</span>
            </p>
          </div>
        </div>

        {/* Traffic Log Table */}
        <div className="bg-white dark:bg-[#131825] rounded-2xl shadow-sm border border-gray-200 dark:border-[#1E2536] overflow-hidden">
          <div className="px-6 py-4 border-b border-gray-200 dark:border-[#1E2536] flex justify-between items-center bg-gray-50 dark:bg-[#0E1220]">
            <h2 className="text-lg font-bold text-gray-800 dark:text-white">Traffic Log</h2>
            <button onClick={fetchLogs} className="text-sm text-[#06B4C9] hover:text-[#06B4C9]/70 font-medium flex items-center gap-1">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
              Refresh
            </button>
          </div>
          <div className="overflow-x-auto max-h-[600px] overflow-y-auto">
            <table className="w-full text-left text-sm text-gray-600 dark:text-[#94A3B8]">
              <thead className="bg-white dark:bg-[#131825] sticky top-0 border-b border-gray-200 dark:border-[#1E2536] z-10">
                <tr>
                  <th className="px-6 py-3 font-semibold text-gray-900 dark:text-[#E2E8F0]">Timestamp</th>
                  <th className="px-6 py-3 font-semibold text-gray-900 dark:text-[#E2E8F0]">Status</th>
                  <th className="px-6 py-3 font-semibold text-gray-900 dark:text-[#E2E8F0]">Method</th>
                  <th className="px-6 py-3 font-semibold text-gray-900 dark:text-[#E2E8F0]">Path</th>
                  <th className="px-6 py-3 font-semibold text-gray-900 dark:text-[#E2E8F0]">Latency</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-[#1E2536]">
                {logs.slice((trafficPage - 1) * TRAFFIC_PER_PAGE, trafficPage * TRAFFIC_PER_PAGE).map((log) => (
                  <tr key={log.id} className="hover:bg-gray-50 dark:hover:bg-[#1E2536]">
                    <td className="px-6 py-3 font-mono text-xs text-gray-500 dark:text-[#64748B] whitespace-nowrap">
                      {new Date(log.created_at).toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                    </td>
                    <td className="px-6 py-3">
                      <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold border ${getStatusColor(log.status)}`}>
                        {log.status}
                      </span>
                    </td>
                    <td className="px-6 py-3 font-bold text-gray-700 dark:text-[#E2E8F0]">{log.method}</td>
                    <td className="px-6 py-3 font-mono text-xs max-w-xs truncate" title={log.path}>
                      {log.path}
                    </td>
                    <td className="px-6 py-3">
                      <span className={`${(log.duration || 0) > 1000 ? 'text-red-500 font-bold' : ''}`}>
                        {log.duration} ms
                      </span>
                    </td>
                  </tr>
                ))}
                {logs.length === 0 && (
                  <tr>
                    <td colSpan={5} className="px-6 py-8 text-center text-gray-500 dark:text-[#94A3B8]">No traffic logs found. Try browsing the app first!</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
          {logs.length > 0 && (
            <div className="px-6 py-2 border-t border-gray-100 dark:border-[#1E2536]">
              <Pagination currentPage={trafficPage} totalItems={logs.length} itemsPerPage={TRAFFIC_PER_PAGE} onPageChange={setTrafficPage} />
            </div>
          )}
        </div>
      </div>
    </AdminLayout>
  );
}

import { createClient } from '@supabase/supabase-js';
import { NextResponse } from 'next/server';
import { headers } from 'next/headers';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function POST(req: Request) {
  try {
    let email = '';
    try {
      const body = await req.json();
      email = body?.email;
    } catch (e) {
      // Empty body is fine
    }

    const headersList = await headers();
    const forwardedFor = headersList.get('x-forwarded-for');
    const ip = forwardedFor ? forwardedFor.split(',')[0] : '127.0.0.1';

    // Query the Rate Limit Table
    const { data: limitRecord } = await supabaseAdmin
      .from('rate_limits')
      .select('*')
      .eq('ip', ip)
      .eq('endpoint', 'login')
      .single();

    const MAX_ATTEMPTS = 5; 
    const WINDOW_MINUTES = 15;

    if (limitRecord) {
      const lastAttempt = new Date(limitRecord.last_attempt).getTime();
      const timeDiffMins = (Date.now() - lastAttempt) / 60000;

      if (timeDiffMins < WINDOW_MINUTES && limitRecord.attempts >= MAX_ATTEMPTS) {
        return NextResponse.json(
          { success: false, message: 'Too many login attempts. Please try again in 15 minutes.' },
          { status: 429 }
        );
      }

      const shouldReset = timeDiffMins >= WINDOW_MINUTES;

      await supabaseAdmin
        .from('rate_limits')
        .update({ 
          attempts: shouldReset ? 1 : limitRecord.attempts + 1, 
          last_attempt: new Date().toISOString() 
        })
        .eq('ip', ip)
        .eq('endpoint', 'login');

    } else {
      await supabaseAdmin.from('rate_limits').insert({
        ip,
        endpoint: 'login',
        attempts: 1,
        last_attempt: new Date().toISOString()
      });
    }

    // 🛑 THE FIX: Safely check for OAuth-Only Account 🛑
    if (email) {
      // 1. Get the user ID from your public users table
      const { data: publicUser } = await supabaseAdmin
        .from('users')
        .select('id')
        .eq('email', email)
        .single();

      if (publicUser) {
        // 2. Fetch the Auth User securely using the Admin API
        const { data: authData } = await supabaseAdmin.auth.admin.getUserById(publicUser.id);

        if (authData?.user?.identities) {
          // 3. Check their connected providers
          const identities = authData.user.identities;
          const hasGoogle = identities.some(identity => identity.provider === 'google');
          const hasEmailPassword = identities.some(identity => identity.provider === 'email');

          // If they have Google but have never set a local password
          if (hasGoogle && !hasEmailPassword) {
            return NextResponse.json(
              { 
                success: false, 
                isOAuthOnly: true,
                message: 'It looks like you signed up with Google. Please log in using Google, or use "Forgot Password" to set up a local password.' 
              },
              { status: 403 }
            );
          }
        }
      }
    }

    return NextResponse.json({ success: true });

  } catch (error) {
    console.error("Login Check Error:", error);
    return NextResponse.json({ success: true }); 
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { createServerClient } from '@supabase/ssr';
import { prisma } from '@/lib/db';
import { genAI, GEMINI_MODEL } from '@/lib/gemini'; // 🛡️ Centralized Gemini (Checkpoint #2)
import { z } from 'zod';

// ---------------------------------------------------------------------------
// POST /api/cvr/analyze
//
// Authenticated endpoint. Accepts a CVR snapshot, enriches it with
// skill_health_cache market data, and returns structured Gemini feedback:
//   - overallScore, summary
//   - skillStrength (strong / moderate / weak buckets)
//   - marketAlignment (score + insight)
//   - missingKeywords (3–6 high-demand gaps)
//   - recommendations (3 actionable next steps)
//
// Consumes 1 Gemini RPD per call. No caching — always fresh analysis.
// 🛡️ SECURITY (Checkpoint #2): Uses centralized Gemini client from @/lib/gemini
// ---------------------------------------------------------------------------

type SkillInfo = {
  id: string;
  name: string;
  verified: boolean;
  tags?: string[];
};

type SkillStrength = {
  strong: string[];
  moderate: string[];
  weak: string[];
};

const analyzeRequestSchema = z.object({
  snapshot: z.record(z.string(), z.any()),
});

export async function POST(req: NextRequest) {
  // -------------------------------------------------------------------------
  // 1. Auth
  // -------------------------------------------------------------------------
  const cookieStore = await cookies();
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll: () => cookieStore.getAll(),
        setAll: () => { },
      },
    }
  );

  const {
    data: { session },
  } = await supabase.auth.getSession();

  if (!session) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 });
  }

  // -------------------------------------------------------------------------
  // 2. Parse + validate body
  // -------------------------------------------------------------------------
  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body.' }, { status: 400 });
  }

  const validation = analyzeRequestSchema.safeParse(body);
  if (!validation.success) {
    return NextResponse.json(
      { error: 'Invalid input.', details: validation.error.format() },
      { status: 400 }
    );
  }

  const { snapshot } = validation.data;

  // -------------------------------------------------------------------------
  // 3. Enrich with skill_health_cache market data
  //    skill_tags are the canonical market keywords; fall back to skill names
  // -------------------------------------------------------------------------
  const skills: SkillInfo[] = snapshot.skills || [];

  // Flatten all unique skill names and tags for health lookups
  const skillNames = Array.from(new Set(
    skills.flatMap((s) => [s.name, ...(s.tags || [])])
  )).filter(Boolean);

  let healthData: {
    skill_name: string;
    health_score: number | null;
    trend_label: string | null;
    job_count: number | null;
    avg_salary: { toNumber(): number } | null;
    confidence: string | null;
  }[] = [];

  if (skillNames.length > 0) {
    try {
      healthData = await prisma.skill_health_cache.findMany({
        where: { skill_name: { in: skillNames } },
        select: {
          skill_name: true,
          health_score: true,
          trend_label: true,
          job_count: true,
          avg_salary: true,
          confidence: true,
        },
      });
    } catch (err) {
      // Non-fatal — analysis proceeds without market enrichment
      console.warn('[cvr/analyze] skill_health_cache fetch failed:', err);
    }
  }

  // -------------------------------------------------------------------------
  // 4. Build Gemini prompt context
  // -------------------------------------------------------------------------
  const skillsContext = skills
    .map((s) => {
      const tags = s.tags || [];
      const tagLine = tags.length > 0 ? ` [Technical Skills: ${tags.join(', ')}]` : '';

      let line = `- CREDENTIAL: "${s.name}"${tagLine} | Status: ${s.verified ? 'Blockchain Verified' : 'Self-reported'}`;

      // Look up health for the main name or its tags
      const healthMatches = healthData.filter(h => 
        h.skill_name === s.name || tags.includes(h.skill_name)
      );

      if (healthMatches.length > 0) {
        // Use the best health score available in the match set
        const bestHealth = healthMatches.reduce((prev, curr) => 
          (curr.health_score || 0) > (prev.health_score || 0) ? curr : prev
        );

        line += ` | Market Health: ${bestHealth.health_score ?? 'N/A'}/100`;
        line += ` | Trend: ${bestHealth.trend_label ?? 'unknown'}`;
        line += ` | Open Jobs: ${bestHealth.job_count ?? 'N/A'}`;

        if (bestHealth.avg_salary) {
          const salary = Math.round(Number(bestHealth.avg_salary)).toLocaleString();
          line += ` | Avg Salary: $${salary}`;
        }
      } else {
        line += ' | No live market data found';
      }
      return line;
    })
    .join('\n');

  const titleCtx = snapshot.title ? `Professional Title: ${snapshot.title}` : '';
  const summaryCtx = snapshot.summary
    ? `Professional Summary: ${snapshot.summary}`
    : '';
  const experienceCtx =
    Array.isArray(snapshot.experience) && snapshot.experience.length > 0
      ? `Work Experience: ${snapshot.experience
        .map((e: { title?: string; company?: string }) =>
          [e.title, e.company].filter(Boolean).join(' at ')
        )
        .filter(Boolean)
        .join('; ')}`
      : '';
  const projectsCtx =
    Array.isArray(snapshot.projects) && snapshot.projects.length > 0
      ? `Projects: ${snapshot.projects
        .map((p: { title?: string }) => p.title)
        .filter(Boolean)
        .join('; ')}`
      : '';
  const certsCtx =
    Array.isArray(snapshot.certifications) && snapshot.certifications.length > 0
      ? `Other Certifications: ${snapshot.certifications
        .map((c: { name?: string }) => c.name)
        .filter(Boolean)
        .join('; ')}`
      : '';
  const educationCtx =
    Array.isArray(snapshot.education) && snapshot.education.length > 0
      ? `Education: ${snapshot.education
        .map((e: { degree?: string; school?: string }) => [e.degree, e.school].filter(Boolean).join(' — '))
        .filter(Boolean)
        .join('; ')}`
      : '';

  const profileLines = [titleCtx, summaryCtx, educationCtx, experienceCtx, projectsCtx, certsCtx]
    .filter(Boolean)
    .join('\n');

  const prompt = `
You are an expert career advisor AI analyzing a student's Credential Verified Resume (CVR).
Blockchain-verified skills carry on-chain proof of completion and are significantly more valuable to employers than self-reported skills.

=== STUDENT CVR PROFILE ===
${profileLines || 'No profile details provided.'}

=== SKILLS WITH LIVE MARKET DATA ===
${skillsContext || 'No skills listed.'}

=== ANALYSIS INSTRUCTIONS ===
Return a single raw JSON object with EXACTLY this structure. No markdown, no code fences, no preamble — raw JSON only:

{
  "overallScore": <integer 0–100, holistic CVR strength based on skills, market alignment, and profile completeness>,
  "summary": "<2–3 sentence assessment of this student's profile strengths and primary opportunity area>",
  "skillStrength": {
    "strong": ["<technical skill name>"],
    "moderate": ["<technical skill name>"],
    "weak": ["<technical skill name>"]
  },
  "marketAlignment": {
    "score": <integer 0–100, how well their verified skills match current market demand>,
    "insight": "<1–2 sentences on market alignment, referencing specific job counts or salary data where available>"
  },
  "missingKeywords": ["<keyword>", "<keyword>", "<keyword>"],
  "recommendations": [
    "<specific, actionable recommendation #1>",
    "<specific, actionable recommendation #2>",
    "<specific, actionable recommendation #3>"
  ]
}

Rules:
- skillStrength: Categorize ONLY the individual technical skills (e.g., "React", "Python", "SQL", "Frontend Development") found in the parentheses or tags. DO NOT use the credential names (like "College Degree" or "Bootcamp") as skills. Base the bucket on health_score (>= 70 = strong, 40–69 = moderate, < 40 = weak). If no market data, default to moderate.
- missingKeywords: 3–6 high-demand skills/technologies that are ABSENT from their profile and would strengthen their market position given their existing skill set and career title.
- recommendations: exactly 3, concrete and specific. Reference their actual skills and market data where relevant.
- overallScore: penalise heavily for self-reported-only skills vs blockchain-verified, and for skills with declining trends.
`;

  // -------------------------------------------------------------------------
  // 5. Call Gemini and parse structured response
  // -------------------------------------------------------------------------
  try {
    const model = genAI.getGenerativeModel({ model: 'gemini-2.5-flash-lite' });
    const result = await model.generateContent(prompt);
    const raw = result.response.text().trim();

    // Strip any accidental markdown fences
    const cleaned = raw.replace(/^```(?:json)?|```$/gm, '').trim();

    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(cleaned);
    } catch (parseErr) {
      console.error('[cvr/analyze] JSON parse failed. Raw response:', raw);
      return NextResponse.json(
        { error: 'Analysis returned an unexpected format. Please try again.' },
        { status: 502 }
      );
    }

    return NextResponse.json({ analysis: parsed });
  } catch (err: unknown) {
    console.error('[cvr/analyze] Gemini error:', err);
    return NextResponse.json(
      { error: 'Analysis failed. Please try again later.' },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/db';
import { randomUUID } from 'crypto';
import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';

export const dynamic = 'force-dynamic';

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { students, batchName } = body;

    // Get the current user (registrar) from auth
    const cookieStore = await cookies();
    const supabase = createServerClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
      {
        cookies: {
          getAll() {
            return cookieStore.getAll();
          },
          setAll(cookiesToSet) {
            try {
              cookiesToSet.forEach(({ name, value, options }) =>
                cookieStore.set(name, value, options)
              );
            } catch (error) {}
          },
        },
      }
    );

    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // 1. Create the Batch Record with the registrar ID
    const batch = await prisma.minting_batches.create({
      data: {
        batch_name: batchName,
        total_students: students.length,
        registrar_id: user.id, // Now properly set the registrar ID
      }
    });

    // 2. Loop through students and save them to DB
    const results = [];

    for (const student of students) {
      // A. Create/Find User
      const userRecord = await prisma.users.upsert({
        where: { wallet_address: student.wallet_address },
        update: {},
        create: {
          id: randomUUID(),
          full_name: student.full_name,
          student_id: student.student_id,
          wallet_address: student.wallet_address,
          email: student.email || `${student.student_id}@student.local`,
          role: 'student'
        }
      });

      // B. Create "Verified Credential" Record
      const credential = await prisma.verified_credentials.create({
        data: {
          user_id: userRecord.id,
          batch_id: batch.id,
          skill_name: student.skill_name,
          token_id: Math.floor(Math.random() * 1000).toString(),
          transaction_hash: "0xMockHash..." + Date.now(),
          issuer_did: "PHINMA-Registrar-01"
        }
      });

      results.push(credential);
    }

    return NextResponse.json({ 
      status: 'success', 
      message: `Successfully processed batch: ${batchName}`,
      mintedCount: results.length
    });

  } catch (error) {
    console.error('Minting Error:', error);
    return NextResponse.json({ status: 'error', message: String(error) }, { status: 500 });
  }
}

