    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Check if user is registrar or super_admin
    const currentUser = await prisma.users.findUnique({
      where: { id: user.id },
      select: { role: true },
    });

    if (currentUser?.role !== 'registrar' && currentUser?.role !== 'super_admin') {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    // 2. Validate request payload
    const body = await req.json();
    const { credentialId } = RevokeSchema.parse(body);

    // 3. Fetch the credential to be revoked
    const credential = await prisma.verified_credentials.findUnique({
      where: { id: credentialId },
      include: { student: { select: { wallet_address: true } } },
    });

    if (!credential) {
      return NextResponse.json({ error: 'Credential not found' }, { status: 404 });
    }

    if (credential.revoked) {
      return NextResponse.json({ error: 'Credential is already revoked' }, { status: 400 });
    }

    // 4. Burn the token on blockchain (Administrative Revocation)
    let transactionHash = null;

    if (credential.token_id) {
      const deployerKey = process.env.DEPLOYER_PRIVATE_KEY;
      if (!deployerKey) {
        console.warn('[revoke] DEPLOYER_PRIVATE_KEY not configured. Performing database-only revocation (Soft Revoke).');
      } else {
        try {
          const rpcUrl = process.env.NEXT_PUBLIC_RPC_URL || 'https://rpc-amoy.polygon.technology/';
          const provider = new ethers.JsonRpcProvider(rpcUrl);
          const signer = new ethers.Wallet(deployerKey, provider);
          const contract = new ethers.Contract(CONTRACT_ADDRESS, VECTOR_TOKEN_ABI, signer);

          // Administrative Revoke: Registrar burns the token on behalf of the student
          const studentWallet = credential.student?.wallet_address;
          if (!studentWallet) throw new Error('Student has no wallet address');

          const tx = await contract.revokeSkill(studentWallet, credential.token_id, 1);
          const receipt = await tx.wait();
          transactionHash = tx.hash;

          console.log(`[revoke] Successfully burned token ${credential.token_id}: ${transactionHash}`);
        } catch (blockchainError: unknown) {
          console.error('[revoke] Blockchain burn failed:', blockchainError);
        }
      }
    }

    // 5. Mark credential as revoked in database
    const updated = await prisma.verified_credentials.update({
      where: { id: credentialId },
      data: {
        revoked: true,
        transaction_hash: transactionHash || credential.transaction_hash,
      },
    });

    return NextResponse.json({ success: true, updated });
  } catch (error: unknown) {
    if (error instanceof z.ZodError) {
      return NextResponse.json({ error: 'Validation failed', details: error.issues }, { status: 400 });
    }
    console.error('[registrar/revoke-credential] POST error:', error);
    return NextResponse.json({ error: 'Failed to revoke credential' }, { status: 500 });
  }
}

import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';
import { prisma } from '@/lib/db';

export const dynamic = 'force-dynamic';

export async function GET(req: Request) {
  const cookieStore = await cookies();

  // 1. Auth check - must be registrar or super_admin
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            );
          } catch (error) {}
        },
      },
    }
  );

  try {
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Check if user is registrar or super_admin
    const currentUser = await prisma.users.findUnique({
      where: { id: user.id },
      select: { role: true, wallet_address: true },
    });

    if (currentUser?.role !== 'registrar' && currentUser?.role !== 'super_admin') {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    // 2. Fetch all minting batches for this registrar
    const batches = await prisma.minting_batches.findMany({
      where: { registrar_id: user.id },
      select: { id: true },
    });

    console.log(`[registrar/users] Found ${batches.length} batches for registrar ${user.id}`);

    const batchIds = batches.map((b) => b.id);

    // 3. Get all credentials from those batches
    let credentialsInBatches: { user_id: string }[] = [];
    if (batchIds.length > 0) {
      credentialsInBatches = await prisma.verified_credentials.findMany({
        where: { batch_id: { in: batchIds } },
        select: { user_id: true },
      });
    }

    console.log(`[registrar/users] Found ${credentialsInBatches.length} credentials in batches`);

    // 4. Extract unique student IDs from batches
    const uniqueStudentIds = new Set(credentialsInBatches.map((c) => c.user_id));

    // 5. As a fallback, also fetch recent credentials created by this registrar
    // that might not have a batch (for backwards compatibility with old issuances)
    // These are identified by issuer_did containing the registrar's wallet or user ID
    if (batches.length === 0) {
      console.log(`[registrar/users] No batches found, looking for direct credentials...`);

      const recentCredentials = await prisma.verified_credentials.findMany({
        where: {
          issued_at: {
            gte: new Date(Date.now() - 365 * 24 * 60 * 60 * 1000) // Last year
          }
        },
        select: { user_id: true, issuer_did: true },
      });

      // Filter credentials issued by this registrar based on issuer_did
      const registrarWallet = `did:polygon:amoy:${currentUser.wallet_address || ''}`;
      const registrarWebDid = `did:web:yourdomain.com:registrar:${user.id}`;

      recentCredentials.forEach(cred => {
        if (cred.issuer_did && 
            (cred.issuer_did.includes(user.id) || 
             cred.issuer_did === registrarWallet || 
             cred.issuer_did === registrarWebDid)) {
          uniqueStudentIds.add(cred.user_id);
        }
      });

      console.log(`[registrar/users] Found ${uniqueStudentIds.size} students from recent credentials`);
    }

    const studentIds = Array.from(uniqueStudentIds);

    // If no credentials exist, return empty array
    if (studentIds.length === 0) {
      console.log(`[registrar/users] No credentials found, returning empty array`);
      return NextResponse.json([]);
    }

    // 6. Fetch only students that this registrar has issued credentials to
    const users = await prisma.users.findMany({
      where: {
        id: { in: studentIds },
        role: 'student',
      },
      select: {
        id: true,
        email: true,
        full_name: true,
        role: true,
        wallet_address: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
      orderBy: { created_at: 'desc' },
    });

    console.log(`[registrar/users] Found ${users.length} student users`);

    // 7. For each user, fetch their credentials issued by this registrar
    const usersWithCredentials = await Promise.all(
      users.map(async (userRecord) => {
        let credentials: { id: string; skill_name: string; issued_at: Date | null; transaction_hash: string | null; token_id: string; revoked: boolean; issuer_did: string | null }[] = [];

        // First try to get credentials from batches
        if (batchIds.length > 0) {
          credentials = await prisma.verified_credentials.findMany({
            where: {
              user_id: userRecord.id,
              batch_id: { in: batchIds },
            },
            select: {
              id: true,
              skill_name: true,
              issued_at: true,
              transaction_hash: true,
              token_id: true,
              revoked: true,
              issuer_did: true,
            },
            orderBy: { issued_at: 'desc' },
          });
        }

        // If no batch credentials found and we have no batches, get all credentials for this user
        // (for backwards compatibility)
        if (credentials.length === 0 && batchIds.length === 0) {
          credentials = await prisma.verified_credentials.findMany({
            where: {
              user_id: userRecord.id,
              issued_at: {
                gte: new Date(Date.now() - 365 * 24 * 60 * 60 * 1000) // Last year
              }
            },
            select: {
              id: true,
              skill_name: true,
              issued_at: true,
              transaction_hash: true,
              token_id: true,
              revoked: true,
              issuer_did: true,
            },
            orderBy: { issued_at: 'desc' },
          });

          // Filter by registrar
          const registrarWallet = `did:polygon:amoy:${currentUser.wallet_address || ''}`;
          const registrarWebDid = `did:web:yourdomain.com:registrar:${user.id}`;

          credentials = credentials.filter(c => 
            c.issuer_did && 
            (c.issuer_did.includes(user.id) || 
             c.issuer_did === registrarWallet || 
             c.issuer_did === registrarWebDid)
          );
        }

        return {
          ...userRecord,
          credentials: credentials.map(c => ({
            id: c.id,
            skill_name: c.skill_name,
            issued_at: c.issued_at,
            transaction_hash: c.transaction_hash,
            token_id: c.token_id,
            revoked: c.revoked,
          })),
          totalCredentials: credentials.length,
          activeCredentials: credentials.filter((c) => !c.revoked).length,
        };
      })
    );

    console.log(`[registrar/users] Returning ${usersWithCredentials.length} users with credentials`);
    return NextResponse.json(usersWithCredentials);
  } catch (error: unknown) {
    console.error('[registrar/users] GET error:', error);
    return NextResponse.json({ error: 'Failed to fetch users' }, { status: 500 });
  }
}

import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';
import { decryptData } from '@/lib/encryption';

export const dynamic = 'force-dynamic';

export async function GET(req: Request) {
  const cookieStore = await cookies();

  // 1. Init Supabase with Service Role to ensure we can fetch data securely
  // independent of restrictive RLS that might block the anon key
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!, 
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            );
          } catch (error) {
            // Safe to ignore in a GET handler: happens if Next.js tries to set 
            // a session cookie in a context where headers are already sent.
          }
        },
      },
    }
  );

  try {
    // 2. 🛡️ Auth Check: Who is asking?
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // 3. 🛡️ Data Fetch: Only fetch for THIS user's ID
    // We strictly use the session ID, ignoring any client inputs
    const { data: credentials, error } = await supabase
      .from('verified_credentials')
      .select('*')
      .eq('user_id', user.id)
      .eq('revoked', false) 
      .order('issued_at', { ascending: false });

    if (error) throw error;

    // 4. 🔓 Server-Side Decryption (Category 3)
    const processedData = (credentials || []).map(cred => {
        let decryptedNote = null;
        if (cred.private_notes) {
            try {
                decryptedNote = decryptData(cred.private_notes);
            } catch (e) {
                console.error(`Decryption failed for cred: ${cred.id}`);
            }
        }
        return {
            ...cred,
            private_notes: decryptedNote
        };
    });

    return NextResponse.json(processedData);

  } catch (err: unknown) {
    console.error("Credential Fetch Error:", err);
    return NextResponse.json({ error: 'Failed to fetch credentials' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/db';
import { createClient } from '@supabase/supabase-js';
import { z } from 'zod';

// --- Types mirroring RichMarketData from adzuna-client ---

interface LocationDemand {
  location: string;
  count: number;
}

interface SalaryInsights {
  min: number | null;
  max: number | null;
  avg: number | null;
  currency: string;
}

interface SnapshotMetadata {
  job_count: number;
  salary: SalaryInsights;
  top_locations: LocationDemand[];
  fetched_at: string;
}

export interface SkillInsight {
  skill_name: string;
  latest_job_count: number;
  salary: SalaryInsights;
  top_locations: LocationDemand[];
  last_updated: string;
  history: { date: string; job_count: number }[]; // Sparkline data
}

// --- Validation ---

const QuerySchema = z.object({
  userId: z.string().uuid('Invalid userId format'),
});

// --- Route Handler ---

export async function GET(req: Request) {
  try {
    const { searchParams } = new URL(req.url);
    const parsed = QuerySchema.safeParse({ userId: searchParams.get('userId') });

    if (!parsed.success) {
      return NextResponse.json(
        { status: 'error', message: 'Missing or invalid userId query parameter' },
        { status: 400 }
      );
    }

    const { userId } = parsed.data;

    // 1. Resolve all skills for this student (verified + self-reported)
    const [verified, selfReported] = await Promise.all([
      prisma.verified_credentials.findMany({
        where: { user_id: userId },
        select: { skill_name: true, skill_tags: true },
      }),
      prisma.self_reported_skills.findMany({
        where: { user_id: userId },
        select: { skill_name: true },
      }),
    ]);

    const allSkills = Array.from(
      new Set([
        ...verified.flatMap(c => 
          (Array.isArray(c.skill_tags) && c.skill_tags.length > 0) ? c.skill_tags : [c.skill_name]
        ),
        ...selfReported.map(s => s.skill_name),
      ])
    );

    if (allSkills.length === 0) {
      return NextResponse.json({ status: 'success', data: [] });
    }

    // 2. Fetch all snapshots for those skills, newest first
    const snapshots = await prisma.market_snapshots.findMany({
      where: { skill_name: { in: allSkills } },
      orderBy: { recorded_at: 'desc' },
      select: {
        skill_name: true,
        job_count: true,
        recorded_at: true,
        metadata: true,
      },
    });

    // 3. Group snapshots by skill and build SkillInsight objects
    const skillMap = new Map<string, typeof snapshots>();

    for (const snap of snapshots) {
      if (!skillMap.has(snap.skill_name)) {
        skillMap.set(snap.skill_name, []);
      }
      skillMap.get(snap.skill_name)!.push(snap);
    }

    const insights: SkillInsight[] = [];

    for (const skill of allSkills) {
      const records = skillMap.get(skill);

      // No market data yet for this skill — still include it with nulls
      // so the UI can show "no data yet" gracefully
      if (!records || records.length === 0) {
        insights.push({
          skill_name: skill,
          latest_job_count: 0,
          salary: { min: null, max: null, avg: null, currency: 'USD' },
          top_locations: [],
          last_updated: '',
          history: [],
        });
        continue;
      }

      // Most recent snapshot drives the headline numbers
      const latest = records[0];
      const meta = latest.metadata as SnapshotMetadata | null;

      // Build sparkline history from all snapshots (oldest → newest)
      const history = [...records]
        .reverse()
        .map(r => ({
          date: new Date(r.recorded_at!).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
          }),
          job_count: r.job_count,
        }));

      insights.push({
        skill_name: skill,
        latest_job_count: latest.job_count,
        salary: meta?.salary ?? { min: null, max: null, avg: null, currency: 'USD' },
        top_locations: meta?.top_locations ?? [],
        last_updated: latest.recorded_at
          ? new Date(latest.recorded_at).toISOString()
          : '',
        history,
      });
    }

    // 4. Sort by job_count descending so highest-demand skills surface first
    insights.sort((a, b) => b.latest_job_count - a.latest_job_count);

    return NextResponse.json({ status: 'success', data: insights });
  } catch (error) {
    console.error('Market Insights Route Failed:', error);
    return NextResponse.json(
      { status: 'error', message: 'Failed to fetch market insights' },
      { status: 500 }
    );
  }
}

