          </div>

          {!loading && filtered.length > 0 && (
            <div className="px-5 py-3 border-t border-gray-100 dark:border-[#1E2536] bg-gray-50/40 dark:bg-[#131825]/60 flex items-center justify-between gap-4 flex-wrap">
