const PROVIDER_PILL: Record<string, string> = {
  udemy:       'bg-purple-100 text-purple-700',
  coursera:    'bg-blue-100 text-blue-700',
  edx:         'bg-slate-100 text-slate-700',
  freecodecamp:'bg-green-100 text-green-700',
  hubspot:     'bg-orange-100 text-orange-700',
};

function providerClass(p: string) {
  return PROVIDER_PILL[p.toLowerCase()] ?? 'bg-[#06B4C9]/10 text-[#06B4C9]';
}

const LEVEL_PILL: Record<string, string> = {
  Beginner:     'bg-green-50 text-green-700 border-green-200',
  Intermediate: 'bg-amber-50 text-amber-700 border-amber-200',
  Advanced:     'bg-red-50 text-red-600 border-red-200',
};

export default function ExploreCourses() {
  const [selectedInterests, setSelectedInterests] = useState<string[]>([]);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [courses, setCourses] = useState<CourseItem[]>([]);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const COURSES_PER_PAGE = 30;

  const toggleInterest = (id: string) => {
    setSelectedInterests(prev =>
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
    setPage(1);
  };

  // Map interest IDs to skill tag keywords for the API
  const INTEREST_TAGS: Record<string, string[]> = {
    'web-dev': ['HTML', 'CSS', 'JavaScript', 'React', 'Node.js', 'Next.js'],
    'data-science': ['Python', 'Machine Learning', 'SQL', 'TensorFlow', 'Data'],
    'cybersecurity': ['Security', 'Pen Testing', 'Network Security', 'Cryptography'],
    'graphic-design': ['Photoshop', 'Illustrator', 'Adobe', 'Design', 'Branding'],
    'cloud': ['AWS', 'Azure', 'GCP', 'Docker', 'Kubernetes', 'Cloud'],
    'mobile': ['Flutter', 'React Native', 'iOS', 'Android', 'Swift', 'Kotlin'],
    'finance': ['Finance', 'Accounting', 'Investing', 'Excel'],
    'marketing': ['SEO', 'Marketing', 'Social Media', 'Ads'],
    'ux': ['Figma', 'UX', 'UI', 'Prototyping', 'User Research'],
    'pm': ['Agile', 'Scrum', 'PMP', 'Project Management'],
    'networking': ['CompTIA', 'Cisco', 'Linux', 'Networking'],
    'game-dev': ['Unity', 'Unreal', 'C#', 'Game Design'],
  };

  const fetchCourses = useCallback(async () => {
    setLoading(true);
    try {
      const tags = selectedInterests.flatMap(id => INTEREST_TAGS[id] || []);
      const params = new URLSearchParams();
      if (search) params.set('q', search);
      if (tags.length > 0) params.set('tags', tags.join(','));
      params.set('page', page.toString());
      params.set('limit', COURSES_PER_PAGE.toString());

      const res = await fetch(`/api/student/courses?${params.toString()}`);
      if (res.ok) {
        const data = await res.json();
        if (data.courses && data.courses.length > 0) {
          setCourses(data.courses.map((c: { id: string; title: string; provider?: string; link?: string; skill_tags?: string[] }) => ({
            id: c.id,
            title: c.title,
            provider: c.provider || 'Unknown',
            link: c.link || '#',
            match: 85,
            tags: c.skill_tags || [],
            level: 'Intermediate' as const,
          })));
          setTotalPages(data.totalPages || 1);
          setLoading(false);
          return;
        }
      }
      // Fallback to hardcoded data if DB is empty
      fallbackToHardcoded();
    } catch {
      fallbackToHardcoded();
    }
    setLoading(false);
  }, [search, selectedInterests, page]);

  // Fallback: use hardcoded COURSES if DB is empty
  const fallbackToHardcoded = () => {
    const ids = selectedInterests.length > 0 ? selectedInterests : Object.keys(COURSES);
    const all = ids.flatMap(id => COURSES[id] ?? []);
    const seen = new Set<string>();
    const unique = all.filter(c => { if (seen.has(c.id)) return false; seen.add(c.id); return true; });
    const q = search.toLowerCase().trim();
    const filtered = q
      ? unique.filter(c =>
          c.title.toLowerCase().includes(q) ||
          c.provider.toLowerCase().includes(q) ||
          c.tags.some(t => t.toLowerCase().includes(q))
        )
      : unique;
    const sorted = filtered.sort((a, b) => b.match - a.match);
    setCourses(sorted.slice((page - 1) * COURSES_PER_PAGE, page * COURSES_PER_PAGE));
    setTotalPages(Math.max(1, Math.ceil(sorted.length / COURSES_PER_PAGE)));
  };

  useEffect(() => { fetchCourses(); }, [fetchCourses]);

  const pagedCourses = courses;

  // Simple pagination control
  function Pagination() {
    if (totalPages <= 1) return null;
    return (
      <div className="flex justify-center items-center gap-2 mt-6">
        <button
          className="px-2 py-1 rounded border text-xs font-medium disabled:opacity-40"
          onClick={() => setPage(p => Math.max(1, p - 1))}
          disabled={page === 1}
        >
          Prev
        </button>
        <span className="text-xs text-gray-500">
          Page {page} of {totalPages}
        </span>
        <button
          className="px-2 py-1 rounded border text-xs font-medium disabled:opacity-40"
          onClick={() => setPage(p => Math.min(totalPages, p + 1))}
          disabled={page === totalPages}
        >
          Next
        </button>
      </div>
    );
  }

  return (
    <DashboardLayout>
      {/* ── Page header ── */}
      <div className="mb-6 flex items-start justify-between gap-4 flex-wrap">
        <div>
          <div className="flex items-center gap-2 text-xs text-gray-400 mb-1">
            <Link href="/student/coach" className="hover:text-[#06B4C9] transition-colors">AI Coach</Link>
            <span>/</span>
            <span className="text-gray-600 font-medium">Explore Courses</span>
          </div>
          <h1 className="text-2xl font-bold text-gray-900 tracking-tight">Explore Courses</h1>
          <p className="text-sm text-gray-400 mt-0.5">Pick your interests and discover courses that match your goals.</p>
        </div>
        {selectedInterests.length > 0 && (
          <button
            onClick={() => setSelectedInterests([])}
            className="text-xs text-gray-400 hover:text-gray-600 underline underline-offset-2 mt-2"
          >
            Clear filters
          </button>
        )}
      </div>

      {/* ── Interest chips ── */}
      <div className="bg-white rounded-xl border border-gray-200 p-5 mb-6">
        <p className="text-sm font-semibold text-gray-700 mb-3">
          What are you interested in?
          <span className="ml-2 text-xs font-normal text-gray-400">Select one or more</span>
        </p>
        <div className="flex flex-wrap gap-2">
          {INTERESTS.map(interest => {
            const active = selectedInterests.includes(interest.id);
            return (
              <button
                key={interest.id}
                onClick={() => toggleInterest(interest.id)}
                className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium border transition-all ${
                  active
                    ? 'bg-[#06B4C9] border-[#06B4C9] text-white shadow-sm shadow-[#06B4C9]/20'
                    : 'bg-white border-gray-200 text-gray-600 hover:border-[#06B4C9] hover:text-[#06B4C9]'
                }`}
              >
                <InterestIcon id={interest.id} />
                {interest.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* ── Search bar ── */}
      <div className="relative mb-5">
        <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-4.35-4.35M17 11A6 6 0 115 11a6 6 0 0112 0z" />
        </svg>
        <input
          type="text"
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Search by title, provider, or skill..."
          className="w-full pl-9 pr-4 py-2.5 text-sm border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#06B4C9] placeholder:text-gray-400 bg-white"
        />
        {search && (
          <button
            onClick={() => setSearch('')}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        )}
      </div>

      {/* ── Results label ── */}
      <div className="flex items-center justify-between mb-3">
        <p className="text-sm text-gray-500">
          {courses.length} course{courses.length !== 1 ? 's' : ''} found
          {selectedInterests.length > 0 && (
            <span className="ml-1 text-gray-400">
              in {selectedInterests.map(id => INTERESTS.find(i => i.id === id)?.label).join(', ')}
            </span>
          )}
        </p>
      </div>

      {/* ── Course grid ── */}
      {courses.length === 0 ? (
        <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
          <div className="w-14 h-14 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-3">
            <svg className="w-7 h-7 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.8}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
            </svg>
          </div>
          <p className="text-sm font-semibold text-gray-600 mb-1">No courses found</p>
          <p className="text-xs text-gray-400">Try a different search or select more interests.</p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {pagedCourses.map((course, i) => (
              <div
                key={course.id}
                className="bg-white border border-gray-200 rounded-xl p-4 hover:shadow-sm hover:border-gray-300 transition-all flex flex-col gap-3"
              >
                {/* Header */}
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-start gap-2.5">
                    <div className="flex-shrink-0 w-7 h-7 rounded-lg bg-gray-100 flex items-center justify-center text-xs font-bold text-gray-500 mt-0.5">
                      {(page - 1) * COURSES_PER_PAGE + i + 1}
                    </div>
                    <div>
                      <p className="text-sm font-semibold text-gray-900 leading-snug">{course.title}</p>
                      <div className="flex items-center gap-2 mt-1 flex-wrap">
                        <span className={`text-xs font-semibold px-2 py-0.5 rounded-md ${providerClass(course.provider)}`}>
                          {course.provider}
                        </span>
                        <span className={`text-xs font-medium px-2 py-0.5 rounded-full border ${LEVEL_PILL[course.level]}`}>
                          {course.level}
                        </span>
                      </div>
                    </div>
                  </div>
                  <span className="flex-shrink-0 text-sm font-bold text-[#06B4C9]">{course.match}%</span>
                </div>

                {/* Tags */}
                <div className="flex flex-wrap gap-1.5">
                  {course.tags.map(tag => (
                    <span key={tag} className="text-xs text-gray-500 border border-gray-200 rounded-full px-2 py-0.5 bg-gray-50">
                      {tag}
                    </span>
                  ))}
                </div>

                {/* CTA */}
                <div className="flex justify-end mt-auto">
                  <a
                    href={course.link}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-xs font-semibold text-gray-500 border border-gray-200 rounded-lg px-3 py-1.5 hover:border-[#06B4C9] hover:text-[#06B4C9] transition-colors bg-white inline-flex items-center gap-1"
                  >
                    Take Course
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                    </svg>
                  </a>
                </div>
              </div>
            ))}
          </div>
          <Pagination />
        </>
      )}
    </DashboardLayout>
  );
}

'use client';
import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import DashboardLayout from '@/components/dashboard/DashboardLayout';
import { useTheme } from '@/contexts/ThemeContext';
import { supabase } from '@/lib/supabaseClient';
import { z } from 'zod'; // 1. Import Zod
import HelpTip from '@/components/shared/HelpTip';

// 2. Define Validation Schema
const profileSchema = z.object({
  firstName: z.string().min(2, "First name must be at least 2 characters").max(50, "First name too long").regex(/^[a-zA-Z\s]*$/, "Name can only contain letters"),
  lastName: z.string().min(2, "Last name must be at least 2 characters").max(50, "Last name too long"),
  phone: z.string().regex(/^\+?[0-9\s-]{7,12}$/, "Phone must be 7-12 characters").optional().or(z.literal('')),
  bio: z.string().max(100, "Bio must be under 100 characters").optional(),
  university: z.string().min(2, "University name is required"),
  major: z.string().max(100, "Major name too long").optional(),
  graduationYear: z.string().regex(/^\d{4}$/, "Year must be 4 digits (e.g. 2026)").optional().or(z.literal('')),
  location: z.string().max(100).optional(),
});

interface ProfileData {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  bio: string;
  university: string;
  major: string;
  graduationYear: string;
  walletAddress: string;
  location: string;
  photoUrl: string;
  studentId: string;
}

interface ProgressItem {
  label: string;
  field: keyof ProfileData | 'account';
  weight: number;
  completed: boolean;
}

export default function ProfilePage() {
  const router = useRouter();
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const { theme, toggleTheme } = useTheme();
  const [userId, setUserId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'profile' | 'preferences' | 'security'>('profile');

  // 3. Add Error State
  const [errors, setErrors] = useState<Record<string, string>>({});

  // 2FA status for security tab
  const [mfa2faEnabled, setMfa2faEnabled] = useState(false);
  const [mfa2faFactorId, setMfa2faFactorId] = useState<string | null>(null); 

  const [formData, setFormData] = useState<ProfileData>({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    bio: '',
    university: 'PHINMA University',
    major: '',
    graduationYear: '',
    walletAddress: '',
    location: '',
    photoUrl: '',
    studentId: '',
  });

  useEffect(() => {
    const loadUserProfile = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();

        if (!session) {
          router.push('/login');
          return;
        }

        setUserId(session.user.id);
        const userEmail = session.user.email || '';

        const { data: userRecord, error } = await supabase
          .from('users')
          .select(`
            full_name, wallet_address, student_id, avatar_url, location,
            profiles ( phone, bio, university, major, graduation_year )
          `)
          .eq('id', session.user.id)
          .single();

        if (error) {
            console.error("Error loading user data:", error);
        }

        if (userRecord) {
          // Capitalize every word in a string
          const capitalizeWords = (s: string) => s.split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()).join(' ');
          const nameParts = (userRecord.full_name || '').split(' ');
          const profile = Array.isArray(userRecord.profiles) ? userRecord.profiles[0] : userRecord.profiles;

          setFormData({
            firstName: capitalizeWords(nameParts[0] || ''),
            lastName: capitalizeWords(nameParts.slice(1).join(' ')) || '',
            email: userEmail,
            walletAddress: userRecord.wallet_address || '',
            location: userRecord.location || '',
            photoUrl: userRecord.avatar_url || '',
            studentId: userRecord.student_id || '',

            phone: profile?.phone || '',
            bio: profile?.bio || '',
            university: profile?.university || 'PHINMA University',
            major: profile?.major || '',
            graduationYear: profile?.graduation_year || '',
          });
        }
      } catch (error) {
        console.error("Error loading profile", error);
      } finally {
        setLoading(false);
      }
    };

    loadUserProfile();
  }, [router]);

  useEffect(() => {
    if (activeTab !== 'security') return;
    const checkMfa = async () => {
      const { data } = await supabase.auth.mfa.listFactors();
      const verified = data?.totp?.filter(f => f.status === 'verified') ?? [];
      if (verified.length > 0) {
        setMfa2faEnabled(true);
        setMfa2faFactorId(verified[0].id);
      } else {
        setMfa2faEnabled(false);
        setMfa2faFactorId(null);
      }
    };
    checkMfa();
  }, [activeTab]);

  const calculateProgress = (): { percentage: number; items: ProgressItem[] } => {
    const progressItems: ProgressItem[] = [
      { label: 'First Name', field: 'firstName', weight: 10, completed: !!formData.firstName },
      { label: 'Last Name', field: 'lastName', weight: 10, completed: !!formData.lastName },
      { label: 'Email', field: 'email', weight: 10, completed: !!formData.email },
      { label: 'Phone', field: 'phone', weight: 10, completed: !!formData.phone },
      { label: 'Location', field: 'location', weight: 10, completed: !!formData.location },
      { label: 'Bio', field: 'bio', weight: 15, completed: !!formData.bio && formData.bio.length > 10 },
      { label: 'MetaMask Wallet', field: 'walletAddress', weight: 15, completed: !!formData.walletAddress && formData.walletAddress.startsWith('0x') },
      { label: 'University', field: 'university', weight: 10, completed: !!formData.university },
      { label: 'Major', field: 'major', weight: 5, completed: !!formData.major },
      { label: 'Graduation Year', field: 'graduationYear', weight: 5, completed: !!formData.graduationYear },
    ];

    const completedWeight = progressItems.filter(item => item.completed).reduce((sum, item) => sum + item.weight, 0);
    const totalWeight = progressItems.reduce((sum, item) => sum + item.weight, 0);
    const percentage = Math.round((completedWeight / totalWeight) * 100);

    return { percentage, items: progressItems };
  };

  const { percentage: profileCompletion, items: progressItems } = calculateProgress();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    let sanitizedValue = value;

    // Phone validation: only allow numbers, spaces, hyphens, and plus sign (max 12 chars)
    if (name === 'phone') {
      sanitizedValue = value.replace(/[^0-9\s+-]/g, '');
      if (sanitizedValue.length > 12) {
        return; // Don't update if exceeds limit
      }
    }
    // Name fields: only letters and spaces (no symbols or emojis)
    else if (name === 'firstName' || name === 'lastName') {
      sanitizedValue = value.replace(/[^a-zA-Z\s]/g, '');
      // Auto-capitalize first letter of each word
      sanitizedValue = sanitizedValue
        .split(' ')
        .map(word => {
          if (word.length === 0) return word;
          return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
        })
        .join(' ');
    }
    // Graduation year: only numbers
    else if (name === 'graduationYear') {
      sanitizedValue = value.replace(/[^0-9]/g, '');
    }
    // Text fields: allow letters, numbers, spaces, and basic punctuation only (no symbols or emojis)
    else if (name === 'bio' || name === 'location' || name === 'major' || name === 'university') {
      // Remove emojis and special symbols, keep letters, numbers, spaces, and basic punctuation (.,'-())
      sanitizedValue = value.replace(/[^a-zA-Z0-9\s.,'\-()]/g, '');
    }

    // Bio validation: max 100 characters
    if (name === 'bio' && sanitizedValue.length > 100) {
      return; // Don't update if exceeds limit
    }

    // Prevent excessive spaces in all text fields (no more than 2 consecutive spaces)
    if (name !== 'phone') {
      sanitizedValue = sanitizedValue.replace(/\s{3,}/g, '  ');
    }

    setFormData({ ...formData, [name]: sanitizedValue });
    // Clear error for this field when user types
    if (errors[name]) {
       setErrors(prev => {
          const newErrors = { ...prev };
          delete newErrors[name];
          return newErrors;
       });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userId) return;
    setSaving(true);
    setErrors({}); // Reset errors

    // 4. Run Zod Validation
    const validationResult = profileSchema.safeParse(formData);

    if (!validationResult.success) {
      const fieldErrors: Record<string, string> = {};
      validationResult.error.issues.forEach(issue => {
        // Path[0] corresponds to the field name
        if (issue.path[0]) fieldErrors[issue.path[0].toString()] = issue.message;
      });
      setErrors(fieldErrors);
      setSaving(false);
      return; // 🛑 Stop submission if validation fails
    }

    try {
      // 1. Update 'users' table
      const { error: userError } = await supabase
        .from('users')
        .update({
          full_name: `${formData.firstName} ${formData.lastName}`.trim(),
          location: formData.location,
