                    <p className="text-[11px] text-gray-500 leading-relaxed">A complete profile increases your chances of getting noticed by employers.</p>
                  </div>
                )}
              </div>

            </div>
          )}
        </div>
      </div>
    </DashboardLayout>
  );
}

