'use client';

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/lib/supabaseClient';
import { useRouter } from 'next/navigation';

// ⏳ CONFIGURATION
const INACTIVITY_LIMIT = 5 * 60 * 1000; // 5 Minutes
const WARNING_DURATION = 60 * 1000;     // Show warning 60 seconds before logout

export default function SessionTimeout() {
  const router = useRouter();
  const [lastActivity, setLastActivity] = useState(Date.now());
  const [showWarning, setShowWarning] = useState(false);
  const [isExpired, setIsExpired] = useState(false); // 🆕 New State for "Logged Out" view
  const [timeLeft, setTimeLeft] = useState(60);

  // 1. Function to handle the final redirect (User clicks button)
  const handleRedirectToLogin = () => {
    router.push('/login?reason=timeout');
  };

  // 2. Background Logout (Happens when timer hits 0)
  const performBackgroundLogout = useCallback(async () => {
    await supabase.auth.signOut();
    setIsExpired(true);
    setShowWarning(false);
  }, []);

  // 3. Reset Timer (Only if not already expired)
  const resetTimer = useCallback(() => {
    if (!showWarning && !isExpired) {
      setLastActivity(Date.now());
    }
  }, [showWarning, isExpired]);

  // 4. Listen for activity
  useEffect(() => {
    const events = ['mousedown', 'keydown', 'scroll', 'touchstart'];
    events.forEach(event => window.addEventListener(event, resetTimer));
    return () => {
      events.forEach(event => window.removeEventListener(event, resetTimer));
    };
  }, [resetTimer]);

  // 5. The "Tick" Loop
  useEffect(() => {
    // If already expired, stop the loop
    if (isExpired) return;

    const interval = setInterval(() => {
      const now = Date.now();
      const timeSinceLastActivity = now - lastActivity;
      const timeUntilLogout = INACTIVITY_LIMIT - timeSinceLastActivity;

      // Case A: Time is UP -> Kill Session & Show "Expired" Modal
      if (timeUntilLogout <= 0) {
        clearInterval(interval);
        performBackgroundLogout();
      } 
      // Case B: Show Warning Countdown
      else if (timeUntilLogout <= WARNING_DURATION) {
        setShowWarning(true);
        setTimeLeft(Math.ceil(timeUntilLogout / 1000));
      } 
      // Case C: Active
      else {
        if (showWarning) setShowWarning(false);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [lastActivity, showWarning, isExpired, performBackgroundLogout]);

  // 6. Button to "Stay Logged In"
  const stayLoggedIn = () => {
    setLastActivity(Date.now());
    setShowWarning(false);
  };

  // --- RENDER LOGIC ---

  // 🔴 STATE 1: SESSION EXPIRED (User is logged out, waiting to go to login)
  if (isExpired) {
    return (
      <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-300">
        <div className="bg-white rounded-2xl shadow-2xl p-8 max-w-sm w-full text-center border-t-4 border-red-500">
          <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
            </svg>
          </div>

          <h3 className="text-xl font-bold text-gray-900 mb-2">Session Expired</h3>
          <p className="text-gray-600 mb-6">
            You have been logged out due to inactivity to protect your account.
          </p>

          <button 
            onClick={handleRedirectToLogin}
            className="w-full px-6 py-3 bg-red-600 hover:bg-red-700 text-white font-bold rounded-xl transition-all shadow-lg hover:shadow-xl transform active:scale-95"
          >
            Log In Again
          </button>
        </div>
      </div>
    );
  }

  // 🟡 STATE 2: WARNING (Counting down)
  if (showWarning) {
    return (
      <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in zoom-in duration-200">
        <div className="bg-white rounded-2xl shadow-2xl p-6 max-w-sm w-full border border-[#06B4C9]">
          <div className="flex flex-col items-center text-center">
            <div className="w-12 h-12 bg-amber-100 rounded-full flex items-center justify-center mb-4">
              <svg className="w-6 h-6 text-amber-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>

            <h3 className="text-lg font-bold text-gray-900 mb-2">Are you still there?</h3>
            <p className="text-gray-500 text-sm mb-6">
              For security, you will be logged out in <br/>
              <span className="text-amber-600 font-bold text-xl">{timeLeft}</span> seconds.
            </p>

            <div className="flex gap-3 w-full">
              <button 
                onClick={performBackgroundLogout}
                className="flex-1 px-4 py-2 border border-gray-200 text-gray-600 rounded-xl hover:bg-gray-50 font-medium transition-colors"
              >
                Log Out
              </button>
              <button 
                onClick={stayLoggedIn}
                className="flex-1 px-4 py-2 bg-[#06B4C9] !text-white rounded-xl hover:bg-[#06B4C9]/90 font-medium shadow-sm transition-colors"
              >
                Stay Active
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return null;
}

'use client';
import { useEffect, useState } from 'react';
import HelpTip from '@/components/shared/HelpTip';
import Pagination from '@/components/shared/Pagination';

// --- Types (mirrors market-insights/route.ts) ---

interface LocationDemand {
  location: string;
  count: number;
}

interface SalaryInsights {
  min: number | null;
  max: number | null;
  avg: number | null;
  currency: string;
}

interface SkillInsight {
  skill_name: string;
  latest_job_count: number;
  salary: SalaryInsights;
  top_locations: LocationDemand[];
  last_updated: string;
  history: { date: string; job_count: number }[];
}

interface Props {
  userId: string;
}

// --- Sparkline SVG ---

function Sparkline({ history, color }: { history: SkillInsight['history']; color: string }) {
  if (history.length < 2) {
    return (
      <div className="h-8 flex items-center">
        <span className="text-xs text-gray-400 italic">No trend data yet</span>
      </div>
    );
  }

  const counts = history.map(h => h.job_count);
  const max = Math.max(...counts) || 1;
  const min = Math.min(...counts);
  const range = (max - min) || 1;
  const w = 80;
  const h = 32;

  const points = counts
    .map((c, i) => {
      const x = (i / (counts.length - 1)) * w;
      const y = h - ((c - min) / range) * h;
      return `${x},${y}`;
    })
    .join(' ');

  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} className="overflow-visible">
      <polyline
        points={points}
        fill="none"
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

// --- Salary Bar ---

function SalaryBar({ salary }: { salary: SalaryInsights }) {
  if (salary.avg === null) {
    return <span className="text-xs text-gray-400 italic">No salary data</span>;
  }

  const fmt = (n: number | null) =>
    n != null ? `$${(n / 1000).toFixed(0)}k` : '—';

  const max = salary.max ?? 1;
  const min = salary.min ?? 0;
  const avg = salary.avg ?? 0;

  // Percentage positions (clamp between 0–100)
  const minPct = Math.min(100, Math.max(0, (min / max) * 100));
  const avgPct = Math.min(98, Math.max(2, (avg / max) * 100));

  return (
    <div className="w-full">
      {/* Bar with avg tick + floating badge */}
      <div className="relative w-full mb-1" style={{ paddingTop: '28px' }}>
        {/* Avg pill badge — floats above the tick */}
        <div
          className="absolute top-0 -translate-x-1/2 bg-[#06B4C9] text-white text-[11px] font-semibold px-2 py-0.5 rounded-md whitespace-nowrap shadow-sm"
          style={{ left: `${avgPct}%` }}
        >
          avg {fmt(avg)}
        </div>

        {/* Track */}
        <div className="relative h-3 w-full bg-gray-100 rounded-full overflow-visible">
          {/* Filled portion: min → avg */}
          <div
            className="absolute top-0 h-full bg-gradient-to-r from-[#06B4C9]/60 to-[#06B4C9] rounded-full"
            style={{ left: `${minPct}%`, width: `${avgPct - minPct}%` }}
          />
          {/* Remainder: avg → max (lighter) */}
          <div
            className="absolute top-0 h-full bg-[#06B4C9]/15 rounded-r-full"
            style={{ left: `${avgPct}%`, width: `${100 - avgPct}%` }}
          />
          {/* Avg tick marker */}
          <div
            className="absolute -top-1 -translate-x-1/2 w-0.5 h-5 bg-[#06B4C9] rounded-full"
            style={{ left: `${avgPct}%` }}
          />
        </div>
      </div>

      {/* Min / Max labels */}
      <div className="flex justify-between text-xs text-gray-400 mt-1">
        <span>{fmt(min)}</span>
        <span>{fmt(max)}</span>
      </div>
    </div>
  );
}

// --- Trend Badge ---

function TrendBadge({ history }: { history: SkillInsight['history'] }) {
  if (history.length < 2) return null;

  const first = history[0].job_count;
  const last = history[history.length - 1].job_count;
  const delta = first > 0 ? ((last - first) / first) * 100 : 0;
  const isUp = delta >= 0;

  return (
    <span
      className={`inline-flex items-center gap-0.5 text-xs font-semibold px-2 py-0.5 rounded-full ${isUp
          ? 'bg-green-50 text-green-700 border border-green-200'
          : 'bg-red-50 text-red-600 border border-red-200'
        }`}
    >
      {isUp ? '▲' : '▼'} {Math.abs(delta).toFixed(0)}%
    </span>
  );
}

// --- Location Bars ---
// Adzuna returns locations as a plain string array with no count values.
// We use rank-based widths: 1st = 100%, 2nd = 80%, 3rd = 60%, 4th = 45%, 5th = 30%
// This gives a natural descending visual without needing real count data.

const RANK_WIDTHS = [100, 80, 60, 45, 30];

function LocationBars({
  locations,
  color,
}: {
  locations: LocationDemand[];
  color: string;
}) {
  if (locations.length === 0) return null;

  // Normalize: handle both string arrays and {location, count} objects from Adzuna
  const normalized = locations.map((loc) =>
    typeof loc === 'string' ? { location: loc, count: 0 } : loc
  );

  // If all counts are identical (including 0), fall back to rank-based widths
  const counts = normalized.map((l) => l.count);
  const allSame = counts.every((c) => c === counts[0]);
  const maxCount = Math.max(...counts) || 1;

  return (
    <div className="space-y-1.5">
      {normalized.map((loc, j) => {
        const width = allSame
          ? RANK_WIDTHS[j] ?? 20
          : Math.round((loc.count / maxCount) * 100);

        return (
          <div key={j} className="flex items-center gap-2">
            <span className="text-xs text-gray-600 w-36 truncate" title={loc.location}>
              {loc.location}
            </span>
            <div className="flex-1 h-1.5 bg-gray-200 rounded-full overflow-hidden">
              <div
                className="h-full rounded-full transition-all duration-300"
                style={{
                  width: `${width}%`,
                  backgroundColor: color,
                  opacity: 0.75,
                }}
              />
            </div>
            {/* Only show count if it's meaningful (non-zero) */}
            {loc.count > 0 && (
              <span className="text-xs text-gray-400 w-8 text-right">{loc.count}</span>
            )}
          </div>
        );
      })}
    </div>
  );
}

// --- Main Component ---

export default function MarketInsightsPanel({ userId }: Props) {
  const [insights, setInsights] = useState<SkillInsight[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const ITEMS_PER_PAGE = 5;

  useEffect(() => {
    if (!userId) return;

    const fetchInsights = async () => {
      try {
        const res = await fetch(`/api/student/market-insights?userId=${userId}`);
        const json = await res.json();
        if (json.status === 'success') {
          setInsights(json.data);
        } else {
          setError(true);
        }
      } catch {
        setError(true);
      } finally {
        setLoading(false);
      }
    };

    fetchInsights();
  }, [userId]);

  const colors = ['#06B4C9', '#22c55e', '#3b82f6', '#f59e0b', '#ef4444', '#06b6d4'];

  if (loading) {
    return (
      <div className="bg-white rounded-xl p-6 border border-gray-200">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h2 className="text-lg font-semibold text-gray-900">Rich Market Intelligence</h2>
            <p className="text-xs text-gray-500">Salary & location demand per skill</p>
          </div>
        </div>
        <div className="space-y-3">
          {[1, 2, 3].map(i => (
            <div key={i} className="h-16 bg-gray-100 rounded-lg animate-pulse" />
